다음은 로그인 처리 컨트롤러의 설계 코드다. 세션통제(세션ID 재할당) 관점에서 취약 여부를 판정하고, 그 근거를 서술하시오. (안전하다면 안전한 이유를, 취약하다면 취약 라인·근거·수정방안을 서술)

```java
protected void doPost(HttpServletRequest req, HttpServletResponse resp) {
    if (authenticate(req)) {
        // 로그인 성공 시 기존 세션을 폐기하고 새 세션을 발급
        HttpSession oldSession = req.getSession(false);
        if (oldSession != null) {
            oldSession.invalidate();
        }
        HttpSession newSession = req.getSession(true);
        newSession.setAttribute("user", req.getParameter("id"));
    }
}
```

